class Solution {
    public int equalPairs(int[][] grid){
        Map<String,Integer> frequency=new HashMap<>();
        for(int[] row:grid)frequency.merge(Arrays.toString(row),1,Integer::sum);
        int n=grid.length,answer=0;
        for(int column=0;column<n;column++){
            int[] values=new int[n];
            for(int row=0;row<n;row++)values[row]=grid[row][column];
            answer+=frequency.getOrDefault(Arrays.toString(values),0);
        }
        return answer;
    }
}

code.kotlin:
class Solution {
    fun equalPairs(grid:Array<IntArray>):Int{
        val frequency=HashMap<String,Int>();
        for(row in grid){
            val key=row.joinToString(",");
            frequency[key]=(frequency[key]?:0)+1
        };
        var answer=0;
        for(column in grid.indices){
            val key=grid.indices.joinToString(","){
                grid[it][column].toString()
            };
            answer+=frequency[key]?:0
        };
        return answer
    }
}

